func TestReproLeak(t *testing.T) {
	baseline := liveGoroutines()
	never := make(chan struct{})
	WarmUp([]string{"a","b"}, func(k string) interface{} { <-never; return nil })
	time.Sleep(50 * time.Millisecond)
	if liveGoroutines() <= baseline { t.Fatal("goroutine not leaked") }
}
